  "kahoot": {
   "titel": "Kahoot!  –  Facebook sicher und selbstbestimmt nutzen  ·  Quiz-Gespräch (Referenzmodul)",
   "hinweise": [
    "Wichtig: Standard im Workshop ist das Karten-Quiz auf den Folien 26–31. Es braucht keinen externen Dienst. Diese Datei nur nutzen, wenn Träger und Datenschutz Kahoot freigegeben haben.",
    "Diese Datei ist eine Vorlage im Kahoot-Format. Vor dem Einsatz im vorhandenen Zugang prüfen, was dort möglich ist: Import dieser Datei, Spiel in Teams, langes Zeit-Limit, Rangliste ausblenden. Nichts zusagen, was nicht geprüft ist.",
    "Möglichst druckarm einstellen: viel Zeit pro Frage, Punkte und Rangliste nicht thematisieren, Team-Namen statt echter Namen, keine Ergebnisse speichern oder exportieren.",
    "In der Spalte Zeit steht 240 Sekunden als Wunsch-Wert. Erst im Team sprechen, dann antworten, dann gemeinsam auflösen. Passende Antwort: Nummer (1–3) in der letzten Spalte.",
    "Kernfragen sind 1, 3 und 5. Sie werden immer gestellt. Reservefragen sind 2, 4 und 6. Sie kommen dazu, wenn Zeit und Aufmerksamkeit reichen."
   ],
   "fragen": [
    {
     "nr": "1",
     "frage": "Du schreibst einen Beitrag. Dabei steht: öffentlich. Wer kann ihn sehen?",
     "antworten": [
      "Nur meine Freunde.",
      "Alle im Internet.",
      "Nur ich."
     ],
     "zeit": "240",
     "richtig": "2"
    },
    {
     "nr": "2",
     "frage": "Eine Freundschafts-Anfrage kommt. Du kennst die Person nicht. Ihr habt viele gemeinsame Freunde. Was machst du?",
     "antworten": [
      "Ich nehme an. Wir haben ja gemeinsame Freunde.",
      "Ich nehme an. Ich kann sie später wieder entfernen.",
      "Ich lehne ab. Oder ich frage eine vertraute Person."
     ],
     "zeit": "240",
     "richtig": "3"
    },
    {
     "nr": "3",
     "frage": "Du willst ein Foto von deiner Kollegin posten. Was machst du zuerst?",
     "antworten": [
      "Ich frage die Kollegin.",
      "Ich poste es ohne ihren Namen.",
      "Ich poste es nur für Freunde."
     ],
     "zeit": "240",
     "richtig": "1"
    },
    {
     "nr": "4",
     "frage": "Du findest einen alten Beitrag von dir. Er ist öffentlich. Was stimmt?",
     "antworten": [
      "Alte Beiträge sieht niemand mehr.",
      "Andere können ihn noch sehen.",
      "Facebook löscht ihn nach einem Jahr."
     ],
     "zeit": "240",
     "richtig": "2"
    },
    {
     "nr": "5",
     "frage": "Ein Freund schreibt dir privat: Ich brauche schnell 200 Euro. Sag es niemandem! Was machst du?",
     "antworten": [
      "Stopp machen. Den Freund anrufen. Einer vertrauten Person zeigen.",
      "Ich schicke das Geld. Er ist ja mein Freund.",
      "Ich frage zurück: Wofür brauchst du das Geld?"
     ],
     "zeit": "240",
     "richtig": "1"
    },
    {
     "nr": "6",
     "frage": "Jemand beleidigt dich immer wieder unter deinen Beiträgen. Was hilft dir?",
     "antworten": [
      "Ich beleidige zurück.",
      "Ich lösche mein Profil.",
      "Zeigen. Blockieren oder melden. Hilfe holen."
     ],
     "zeit": "240",
     "richtig": "3"
    }
   ]
  },
