     "Lernziel": "Wissen, wo das Thema zum Weiterüben liegt; die Seite öffnen können.",
     "Methode": "QR-Code scannen, kurz zeigen.",
     "Sozialform": "Plenum, einzeln",
     "Zeit": "ca. 2 Min",
     "Material": "eigenes Handy, QR-Code",
     "Hinweis": "Der QR-Code ist der Hauptweg; die volle Adresse steht im Feld Lernplattform und im Ausdruck dieses Leitfadens, nicht klein auf der Folie. Zeigen: Sprache umstellen, Vorlesen, Kurz-Modus, Quiz, Merk-Karte und die Alltags-Übung „Ein Konzert-Foto teilen“ als erster Schritt für alle. Vertiefung: Stories (L3), Standort (L4), bearbeitete Bilder (L7). Die Lektion private Nachrichten (L5), die Quizfrage 3 und das Übungs-Handy enthalten Inhalte zu privaten Fotos – diese nur begleitet und angekündigt öffnen, nicht im Standardweg. Die Sprache lässt sich jederzeit umstellen. Vor dem Workshop an einem Gerät ohne gespeicherte Einstellungen testen, was der QR-Code zuerst zeigt. Zum Datenschutz nur das sagen, was auf der Datenschutz-Seite der Lernplattform steht (Stand Juni 2026): Die Seite fragt nicht nach dem Namen, es gibt kein Konto und keine Werbung; der Lernstand bleibt nur nach Zustimmung auf dem Gerät; beim Aufruf verarbeitet der Hoster GitHub Pages technisch nötige Daten wie die IP-Adresse. Keine pauschale Aussage, es würden gar keine personenbezogenen Daten verarbeitet.",
     "Lernplattform": "alex-und-tilda.github.io/sicher-und-selbstbestimmt-im-internet/#thema-instagram; weitere Einstiege: #thema-instagram:kurz, #thema-instagram:quiz, #thema-instagram:merk, #alltag:foto:start."
