     "Hinweis": "Mindestziel ist eine Einstellung: Geist-Modus an. Wer das geschafft hat, ist fertig; das ausdrücklich sagen. Bis zu zwei weitere Einstellungen sind freiwillig: Wer darf mich kontaktieren und Wer darf meine Story sehen – beide auf Meine Freunde. Die Praxis dauert 15 Minuten; die Zeit geht in Ruhe, Wiederholung und Einzelhilfe. Pro Einstellung erst am Beamer auf der Praxis-Seite zeigen, dann machen alle mit. Die Begleitung zeigt, die Person tippt. Keine Passwörter eingeben oder vorlesen. Menüwege stehen nur auf der Praxis-Seite; weicht die App ab: in den Einstellungen nach dem Wort suchen. Beim Geist-Modus die Auswahl „Bis zum Ausschalten“ nehmen. Blockieren und Melden nur zeigen. Erfolge abhaken. Die Praxis-Seite hat außerdem „Nicht als Vorschlag erscheinen“ und „Über die Handynummer nicht gefunden werden“; beides ist nicht Teil dieses Workshops.",
