     "Material": "eigenes Handy, WLAN, QR-Code",
     "Hinweis": "Der QR-Code ist der Hauptweg. Er wird vor dem Workshop getestet. Klappt das Scannen nicht: Die Begleitung öffnet die Seite auf dem Handy der Person oder zeigt sie am Beamer. Die volle Adresse steht unten im Feld Lernplattform und im Ausdruck dieses Leitfadens; sie wird nicht zum Abtippen an die Wand geworfen. Kein externer Kurz-Link-Dienst. Ohne Handy oder ohne Konto ist der Standardweg das Übungs-Handy „Trends und Zeit“ (#thema-tiktok:uebung) – erfundene Personen, kein Konto nötig. Im Workshop kein Konto anlegen.",
     "Lernplattform": "Praxis-Seite alex-und-tilda.github.io/sicher-und-selbstbestimmt-im-internet/praxis/tiktok.html (Stand der Seite: Juni 2026 – vor dem Einsatz prüfen)."
