    "notizen": {
     "Lernziel": "Mindestens eine Einstellung selbst vornehmen: Konto auf privat stellen.",
     "Methode": "Angeleitete Übung am Gerät; Tandem.",
     "Sozialform": "Tandem, einzeln mit Begleitung",
     "Zeit": "ca. 12 Min",
     "Material": "eigenes Handy, Praxis-Seite, Beamer",
     "Hinweis": "Mindestziel ist eine Einstellung: Konto auf privat. Wer das geschafft hat, ist fertig; das ausdrücklich sagen. Bis zu zwei weitere Aufgaben sind freiwillig: Wer darf kommentieren, und einen Timer für die Pause stellen. Wichtig für Menschen ohne TikTok-Konto: Für sie ist der Timer in der Uhr-App des Handys die Pflicht-Handlung – auf der Praxis-Seite gibt es dazu keinen Abschnitt, deshalb zeigt die Begleitung das an der Uhr-App. Die Praxis dauert 15 Minuten; die Zeit geht in Ruhe, Wiederholung und Einzelhilfe. Pro Aufgabe erst am Beamer zeigen, dann machen alle mit. Die Begleitung zeigt, die Person tippt. Keine Passwörter eingeben oder vorlesen. Menüwege stehen nur auf der Praxis-Seite; weicht die App ab: oben in den Einstellungen suchen. Blockieren und Melden nur zeigen. Erfolge abhaken. Die Praxis-Seite hat außerdem Wer darf dir schreiben, Duett und Stitch, Video-Downloads, Konto nicht vorschlagen und Aktivitätsstatus; diese Punkte sind nicht Teil dieses Workshops.",
     "Lernplattform": "Praxis-Seite TikTok (Konto auf privat, Wer darf kommentieren, Wer darf dir schreiben, Blockieren, Melden). Ohne Handy oder Konto: Übungs-Handy „Trends und Zeit“ (#thema-tiktok:uebung)."
    },
