  "kahoot": {
   "titel": "Kahoot!  –  TikTok sicher und selbstbestimmt nutzen  ·  Quiz-Gespräch (Referenzmodul)",
   "hinweise": [
    "Wichtig: Standard im Workshop ist das Karten-Quiz auf den Folien 27–32. Es braucht keinen externen Dienst. Diese Datei nur nutzen, wenn Träger und Datenschutz Kahoot freigegeben haben.",
    "Diese Datei ist eine Vorlage im Kahoot-Format. Vor dem Einsatz im vorhandenen Zugang prüfen, was dort möglich ist: Import dieser Datei, Spiel in Teams, langes Zeit-Limit, Rangliste ausblenden. Nichts zusagen, was nicht geprüft ist.",
    "Möglichst druckarm einstellen: viel Zeit pro Frage, Punkte und Rangliste nicht thematisieren, Team-Namen statt echter Namen, keine Ergebnisse speichern oder exportieren.",
    "In der Spalte Zeit steht 240 Sekunden als Wunsch-Wert. Erst im Team sprechen, dann antworten, dann gemeinsam auflösen. Passende Antwort: Nummer (1–3) in der letzten Spalte.",
    "Kernfragen sind 1, 3 und 5. Sie werden immer gestellt. Reservefragen sind 2, 4 und 6. Sie kommen dazu, wenn Zeit und Aufmerksamkeit reichen."
   ],
   "fragen": [
    {
     "nr": "1",
     "frage": "Dein Konto ist privat. Eine fremde Person will dir folgen. Was passiert?",
     "antworten": [
      "Sie sieht sofort alle deine Videos.",
      "Du musst es erst erlauben.",
      "TikTok entscheidet für dich."
     ],
     "zeit": "240",
     "richtig": "2"
    },
    {
     "nr": "2",
     "frage": "In deinem Video sieht man das Straßen-Schild vor deinem Haus. Was machst du?",
     "antworten": [
      "Ich nehme das Video neu auf.",
      "Ich poste es so. Das sieht keiner.",
      "Ich mache das Video etwas dunkler."
     ],
     "zeit": "240",
     "richtig": "1"
    },
    {
     "nr": "3",
     "frage": "Bei einem Trend sollen alle lange die Luft anhalten. Viele machen mit. Was machst du?",
     "antworten": [
      "Ich mache nur kurz mit.",
      "Ich filme einen Freund dabei.",
      "Ich mache nicht mit. Das kann gefährlich sein."
     ],
     "zeit": "240",
     "richtig": "3"
    },
    {
     "nr": "4",
     "frage": "Eine Person schreibt: Ich schicke dir ein Geschenk. Schreib mir deine Adresse. Was machst du?",
     "antworten": [
      "Ich schreibe nur die Straße.",
      "Ich schreibe die Adresse. Ein Geschenk ist nett.",
      "Ich schreibe keine Adresse. Ich zeige es einer vertrauten Person."
     ],
     "zeit": "240",
     "richtig": "3"
    },
    {
     "nr": "5",
     "frage": "Es ist spät. Du schaust schon lange Videos. Das nächste Video startet von allein. Was hilft dir?",
     "antworten": [
      "Das Handy weglegen. Eine Pause machen.",
      "Noch 3 Videos schauen. Dann Schluss.",
      "Den Ton ausmachen und weiter-schauen."
     ],
     "zeit": "240",
     "richtig": "1"
    },
    {
     "nr": "6",
     "frage": "Unter deinem Video machen sich mehrere Personen über dich lustig. Was hilft dir?",
     "antworten": [
      "Ich lese die Kommentare immer wieder.",
      "Zeigen. Blockieren oder melden. Hilfe holen.",
      "Ich schreibe etwas Gemeines zurück."
     ],
     "zeit": "240",
     "richtig": "2"
    }
   ]
  },
