     "Hinweis": "Achtsam starten. Das Thema kann Betroffene berühren. Ziel in einem Satz: Heute erkennen wir Cybermobbing, und wir üben, wie man Hilfe holt. Ausdrücklich sagen: Niemand muss etwas Eigenes erzählen. Wer eine Pause braucht, darf rausgehen.",
