     "Hinweis": "Der QR-Code ist der Hauptweg; die volle Adresse steht im Feld Lernplattform und im Ausdruck dieses Leitfadens, nicht klein auf der Folie. Wichtig und ehrlich sagen: Zu Cybermobbing gibt es auf der Lernplattform kein eigenes Thema. Passend ist das Thema Hilfe bei Problemen – dort steht der ganze Plan. Verletzende Kommentare stehen außerdem in den App-Themen: Instagram L6, Facebook L6, TikTok L6. Blockieren und Melden stehen auf den Praxis-Seiten der Apps. Die Sprache lässt sich jederzeit umstellen. Vor dem Workshop an einem Gerät ohne gespeicherte Einstellungen testen, was der QR-Code zuerst zeigt. Zum Datenschutz nur das sagen, was auf der Datenschutz-Seite der Lernplattform steht (Stand Juni 2026): Die Seite fragt nicht nach dem Namen, es gibt kein Konto und keine Werbung; der Lernstand bleibt nur nach Zustimmung auf dem Gerät; beim Aufruf verarbeitet der Hoster GitHub Pages technisch nötige Daten wie die IP-Adresse.",
